        pub fn @"body"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"fun", 7, "ir.Fun.body");
        }
        pub fn @"owner"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"fun", 8, "ir.Fun.owner");
        }
        pub fn @"owner_params"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"fun", 9, "ir.Fun.owner_params");
        }
        pub fn @"mark"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"fun", 10, "ir.Fun.mark");
        }
    };
    pub const Sub = struct {
        pub fn @"name"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"sub", 1, "ir.Sub.name");
        }
        pub fn @"tparams"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"sub", 2, "ir.Sub.tparams");
        }
        pub fn @"params"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"sub", 3, "ir.Sub.params");
        }
        pub fn @"fails"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"sub", 4, "ir.Sub.fails");
        }
        pub fn @"keeps"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"sub", 5, "ir.Sub.keeps");
        }
        pub fn @"body"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"sub", 6, "ir.Sub.body");
        }
        pub fn @"owner"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"sub", 7, "ir.Sub.owner");
        }
        pub fn @"owner_params"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"sub", 8, "ir.Sub.owner_params");
        }
        pub fn @"mark"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"sub", 9, "ir.Sub.mark");
        }
    };
    pub const Lambda = struct {
        pub fn @"captures"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"lambda", 1, "ir.Lambda.captures");
        }
        pub fn @"params"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"lambda", 2, "ir.Lambda.params");
        }
