        .@"star" => 187,
        .@"tilde" => 188,
        .@"caret" => 189,
        .@"minus" => 191,
        .@"slash" => 192,
        .@"percent" => 193,
        .@"gt" => 204,
        .@"dollar" => 227,
        .@"ampersand" => 232,
        .@"fixed_assign" => 121,
        .@"plus_assign" => 134,
        .@"minus_assign" => 135,
        .@"star_assign" => 136,
        .@"slash_assign" => 137,
        .@"percent_assign" => 138,
        .@"plus_wrap_assign" => 139,
        .@"minus_wrap_assign" => 140,
        .@"star_wrap_assign" => 141,
        .@"plus_sat_assign" => 142,
        .@"minus_sat_assign" => 143,
        .@"amp_assign" => 144,
        .@"bar_assign" => 145,
        .@"caret_assign" => 146,
        .@"lshift_assign" => 147,
        .@"lshift_wrap_assign" => 148,
        .@"rshift_assign" => 149,
        .@"arrow" => 159,
        .@"eq" => 178,
        .@"ne" => 203,
        .@"le" => 205,
