/// Slot of `role` in nodes of `kind` (the head is slot 0).
fn slotOf(kind: Tag, role: Role) ?usize {
    return switch (kind) {
        .@"use" => switch (role) {
            .@"name" => 1,
            .@"alias" => 2,
            else => null,
        },
        .@"fun" => switch (role) {
            .@"name" => 1,
            .@"tparams" => 2,
            .@"params" => 3,
            .@"returns" => 4,
            .@"origins" => 5,
            .@"keeps" => 6,
            .@"body" => 7,
            .@"owner" => 8,
            .@"owner_params" => 9,
            .@"mark" => 10,
            else => null,
        },
        .@"sub" => switch (role) {
            .@"name" => 1,
            .@"tparams" => 2,
            .@"params" => 3,
            .@"fails" => 4,
            .@"keeps" => 5,
            .@"body" => 6,
